export const slug = "magnetic-wireless-charger-case-alignment";
export const title = "How to Check a Magnetic Wireless Charger With Your Phone Case";
export const metaTitle = "Magnetic Wireless Chargers and Phone Cases";
export const metaDescription = "Check phone, charger, case, power supply, alignment, orientation, and removal before choosing a magnetic wireless charging setup.";
export const author = "Jamie Cole, Lead Product Researcher";
export const datePublished = "2026-10-31";
export const readTime = "11 min";
